<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createAsyncDiagnosisApi,initialDiagnosisState,createAsyncDiagnosisFlow,SERVICE_MODES} from '../../services/async-diagnosis.js'
import {couponLocalTime,couponUtcTime} from '../../services/coupons.js'
import {createDiagnosisRecovery} from '../../services/diagnosis-recovery.js'
import {imageRequestKey} from '../../services/private-images.js'
const state=reactive(initialDiagnosisState()),editing=ref(0),form=reactive({mode:'AVAILABLE',note:'',fromDate:'',fromTime:'',toDate:'',toTime:'',revision:0}),modes=Object.keys(SERVICE_MODES),api=createAsyncDiagnosisApi(),allowed=()=>operatorSession.canDiagnoseManage
const recovery=createDiagnosisRecovery({actor:()=>operatorSession.actorId,role:()=> 'admin',scope:()=> 'diagnosis-service-policy'})
const flow=createAsyncDiagnosisFlow({state,recovery,token:operatorToken,allowed,scope:()=> 'diagnosis-service-policy',newKey:imageRequestKey,load:api.policies,write:(t,a,id,b,k)=>api.policyWrite(t,a,id,b,k),onWritten:clearForm,confirm:action=>new Promise(resolve=>uni.showModal({title:action==='discard-local'?'清理本机待核对请求':'确认诊断受理配置',content:action==='discard-local'?'请先核对刚读取的服务器配置列表。确认仅清除本机原请求，不删除服务器配置，不重发；后续新建或修改必须重新确认。':'发布后条款冻结。来源及有效期须可核对，不授予处理权限。确认后原请求在本机保留；23小时内可原键重试，过期须核对服务器配置后手动清理。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}))})
let visible=false;function clearForm(){editing.value=0;Object.assign(form,{mode:'AVAILABLE',note:'',fromDate:'',fromTime:'',toDate:'',toTime:'',revision:0})}
function edit(p){editing.value=p.id;Object.assign(form,{mode:p.mode,note:p.source_note,revision:p.revision});[form.fromDate,form.fromTime]=couponLocalTime(p.valid_from).split(' ');[form.toDate,form.toTime]=couponLocalTime(p.valid_to).split(' ')}
function save(){const from=couponUtcTime(form.fromDate,form.fromTime),to=couponUtcTime(form.toDate,form.toTime);if(!from||!to||Date.parse(to)<=Date.parse(from)||[...form.note.trim()].length<2||[...form.note.trim()].length>256){state.message='请填写可核对的来源和生效/截止时间。';return}flow.save(editing.value?'update':'create',editing.value,{mode:form.mode,source_note:form.note.trim(),valid_from:from,valid_to:to,...(editing.value?{expected_revision:form.revision}:{})})}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function reset(){flow.reset();clearForm()}watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){clearForm()}})
</script>
<template><view class="reservation-page"><text class="reservation-title">非实时诊断受理配置</text><button @tap="uni.navigateTo({url:'/pages/diagnosis/notifications?role=admin'})">诊断站内消息</button><text>独立诊断管理权限；未配置、到期或缺有效诊断人员时不接受新留言。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有诊断管理权限。</text><template v-else><view class="reservation-panel"><text>{{editing?'修改草稿':'新建受理草稿'}}</text><picker :range="modes.map(m=>SERVICE_MODES[m])" :value="modes.indexOf(form.mode)" :disabled="state.busy||state.retry" @change="form.mode=modes[Number($event.detail.value)]"><view>{{SERVICE_MODES[form.mode]}}</view></picker><input v-model="form.note" maxlength="256" :disabled="state.busy||state.retry" placeholder="面向车主的受理来源说明"/><text>北京时间生效日期与时间</text><input v-model="form.fromDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.fromTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/><text>北京时间截止日期与时间</text><input v-model="form.toDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.toTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/><button :disabled="state.busy||state.retry" @tap="save">保存草稿</button><button :disabled="state.busy||state.retry" @tap="clearForm">新建另一配置</button></view><text v-if="state.message">{{state.message}}</text><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原操作</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器配置并清理本机恢复记录</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新</button><template v-if="state.data"><text v-if="!state.data.items.length">暂无受理配置。</text><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text>{{SERVICE_MODES[p.mode]}} · {{p.status}} · 版本 {{p.revision}}</text><text>{{p.source_note}}</text><text>{{couponLocalTime(p.valid_from)}} 至 {{couponLocalTime(p.valid_to)}}</text><button v-if="p.status==='DRAFT'" :disabled="state.busy||state.retry" @tap="edit(p)">修改草稿</button><button v-if="p.status==='DRAFT'" :disabled="state.busy||state.retry" @tap="flow.save('status',p.id,{expected_revision:p.revision,status:'PUBLISHED'})">发布冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="state.busy||state.retry" @tap="flow.save('status',p.id,{expected_revision:p.revision,status:'STOPPED'})">停止此配置</button></view><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页</button><button v-if="state.page*20<state.data.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页</button></template><button @tap="uni.navigateTo({url:'/pages/operator/diagnosis-cases'})">进入诊断处理工作区</button></template></view></template>
